:root {
  --ink: #1d1a17; --green: #b0703a; --green-deep: #8a5527; --muted: #6d655c;
  --line: #e4dcd1; --sage: #f4efe8; --sage-2: #ede5da; --paper: #f7f3ed;
  --cream: #efe7db; --dark: #1e1a16; --darker: #12100e;
  --shadow: 0 14px 40px rgba(29, 26, 23, 0.08);
}
.btn-nx-outline { border-color: #d8b896; }
.btn-nx:hover { box-shadow: 0 10px 22px rgba(176, 112, 58, 0.22); }
.plan-card .plan-badge { box-shadow: 0 6px 14px rgba(176, 112, 58, 0.25); }
.plan-card.is-featured { box-shadow: 0 0 0 1.5px var(--green), 0 22px 44px rgba(29, 26, 23, 0.14); }
.nx-stars { color: #c9a27a; }
.nav-dark-wrap { background: var(--darker); }
.nav-dark-wrap::after { background: rgba(18, 16, 14, 0.74); }
.nx-nav-dark { background: rgba(18, 16, 14, 0.72); }
.nx-hero-slide { background-color: var(--paper); }
.nx-hero .nx-hero-slide::before {
  background: linear-gradient(90deg, rgba(247, 243, 237, 0.9) 0%, rgba(247, 243, 237, 0.66) 32%, rgba(247, 243, 237, 0.14) 56%, rgba(247, 243, 237, 0) 70%);
}
.nx-footer-dark, .nx-footer-dark a { color: #efe7db; }
.nx-footer-dark .muted { color: #b8ab9c; }
.foot-cta {
  background:
    radial-gradient(60% 120% at 88% 0%, rgba(176, 112, 58, 0.5) 0%, transparent 60%),
    radial-gradient(50% 110% at 6% 100%, rgba(226, 173, 120, 0.3) 0%, transparent 60%),
    linear-gradient(115deg, var(--darker) 0%, var(--dark) 55%, var(--green-deep) 100%);
}
.foot-cta h2 .em { color: #e2ad78; }
.foot-cta p, .foot-form input::placeholder, .foot-form-note { color: #b8ab9c; }
.bk-steps .is-done button, .bk-pro:hover { border-color: #d8b896; }
.bk-steps .is-done span { background: #f0e2d1; }
.bk-pro[aria-pressed="true"] { background: var(--sage); }
@media (max-width: 767.98px) {
  .nx-hero .nx-hero-slide::before {
    background: linear-gradient(180deg, rgba(247, 243, 237, 0.95) 0%, rgba(247, 243, 237, 0.84) 36%, rgba(247, 243, 237, 0.32) 60%, rgba(247, 243, 237, 0) 80%);
  }
}
.nav-dark-wrap::before { background-image: url("img/rubros/barberia/hero-2.jpg"); }
.nx-hero { background: var(--darker); }
.nx-hero-slide { background-color: var(--darker); }
.nx-hero .nx-hero-slide::before {
  background: linear-gradient(90deg, rgba(18, 16, 14, 0.94) 0%, rgba(18, 16, 14, 0.74) 34%, rgba(18, 16, 14, 0.2) 60%, rgba(18, 16, 14, 0) 74%);
}
.nx-hero .nx-display { color: #fff; }
.nx-hero .nx-display .em { color: #e2ad78; }
.nx-hero .nx-lead { color: rgba(255, 255, 255, 0.78); }
@media (max-width: 767.98px) {
